672	icruiksh	20	1030	import java.util.*;\r\n\r\npublic class Main {\r\n    public static void main(String[] args) {\r\n        Scanner scan = new Scanner(System.in);\r\n        int n = scan.nextInt();\r\n        int k = scan.nextInt();\r\n        int numFood = k;\r\n\r\n        Chamber[] chambers = new Chamber[n];\r\n        for(int i = 0; i < n; i++) {\r\n            chambers[i] = new Chamber();\r\n        }\r\n\r\n        // Create Graph\r\n        for(int i = 0; i < n - 1; i++) {\r\n            int a = scan.nextInt();\r\n            int b = scan.nextInt();\r\n            int d = scan.nextInt();\r\n\r\n            Chamber chamberA = chambers[a - 1];\r\n            Chamber chamberB = chambers[b - 1];\r\n\r\n            Connection connection = new Connection(d, chamberA, chamberB);\r\n            chamberA.connections.add(connection);\r\n            chamberB.connections.add(connection);\r\n        }\r\n\r\n        // Set Food\r\n        for(int i = 0; i < k; i++) {\r\n            int f = scan.nextInt();\r\n            chambers[f - 1].hasFood = true;\r\n        }\r\n\r\n        // Graph setting done\r\n\r\n        LinkedList<Path> pathsQ = new LinkedList<>();\r\n        Path initialPath = new Path(0, chambers[0]);\r\n        pathsQ.add(initialPath);\r\n\r\n        // BFS\r\n        while(true) {\r\n            Path currentPath = pathsQ.removeFirst();\r\n\r\n            // Loop through connections\r\n            for(int i = 0; i < currentPath.getNumConnections(); i++) {\r\n                Path connectedPath = currentPath.clone();\r\n                connectedPath.goToConnection(i);\r\n                // Check if we are done\r\n                if(connectedPath.getNumFoodCollected() == numFood && connectedPath.currentChamber == chambers[0]) {\r\n                    System.out.println(connectedPath.distanceTravelled);\r\n                    scan.close();\r\n                    return;\r\n                }\r\n                pathsQ.add(connectedPath);\r\n            }\r\n        }\r\n    }\r\n\r\n    private static class Chamber {\r\n        public boolean hasFood = false;\r\n        public ArrayList<Connection> connections = new ArrayList<>();\r\n    }\r\n\r\n    private static class Connection {\r\n        public int distance = 0;\r\n        public Chamber chamberA = null;\r\n        public Chamber chamberB = null;\r\n\r\n        public Connection(int distance, Chamber chamberA, Chamber chamberB) {\r\n            this.distance = distance;\r\n            this.chamberA = chamberA;\r\n            this.chamberB = chamberB;\r\n        }\r\n\r\n        public Chamber getOtherChamber(Chamber chamber) {\r\n            if(chamber == chamberA) {\r\n                return chamberB;\r\n            }\r\n            else if(chamber == chamberB) {\r\n                return chamberA;\r\n            }\r\n            else {\r\n                return null;\r\n            }\r\n        }\r\n    }\r\n\r\n    private static class Path {\r\n        public int distanceTravelled = 0;\r\n        public Chamber currentChamber = null;\r\n        public ArrayList<Chamber> foodChambersVisited = new ArrayList<>();\r\n\r\n        public Path(int distanceTravelled, Chamber currentChamber) {\r\n            this.distanceTravelled = distanceTravelled;\r\n            this.currentChamber = currentChamber;\r\n        }\r\n\r\n        @Override\r\n        public Path clone() {\r\n            Path pathClone = new Path(distanceTravelled, currentChamber);\r\n            for(int i = 0; i < this.foodChambersVisited.size(); i++) {\r\n                pathClone.foodChambersVisited.add(this.foodChambersVisited.get(i));\r\n            }\r\n            return pathClone;\r\n        }\r\n\r\n        public int getNumConnections() {\r\n            return currentChamber.connections.size();\r\n        }\r\n\r\n        public void goToConnection(int connectionIndex) {\r\n            Chamber connectedChamber = currentChamber.connections.get(connectionIndex).getOtherChamber(currentChamber);\r\n            int distance = currentChamber.connections.get(connectionIndex).distance;\r\n\r\n            this.currentChamber = connectedChamber;\r\n            this.distanceTravelled += distance;\r\n\r\n            if(currentChamber.hasFood && !foodChambersVisited.contains(currentChamber)) {\r\n                foodChambersVisited.add(currentChamber);\r\n            }\r\n        }\r\n\r\n        public int getNumFoodCollected() {\r\n            return foodChambersVisited.size();\r\n        }\r\n    }\r\n}	WA on case 0, test 1	WA	Java17	2023-01-02 12:32:15.124075	0
