3292	mhq2	40	1084	#include <iostream>\r\n#include <vector>\r\n#include <iomanip>\r\n\r\n// Function to generate a spiral matrix filled with alphabets.\r\nstd::vector<std::vector<char>> generateAlphabetSpiral(int n) {\r\n    // Initialize the matrix with spaces to later fill with characters.\r\n    std::vector<std::vector<char>> matrix(n, std::vector<char>(n, ' '));\r\n\r\n    // Variables representing the bounds of the current loop iteration.\r\n    int top = 0, bottom = n - 1, left = 0, right = n - 1;\r\n\r\n    // Current character to fill in the matrix.\r\n    char currentChar = 'A';\r\n\r\n    while (true) {\r\n        // Check if we've filled the whole matrix.\r\n        if (left > right) {\r\n            break;\r\n        }\r\n\r\n        // Fill from left to right.\r\n        for (int i = left; i <= right; ++i) {\r\n            matrix[top][i] = currentChar;\r\n            currentChar = currentChar == 'Z' ? 'A' : currentChar + 1;  // Loop back to 'A' after 'Z'.\r\n        }\r\n        ++top;\r\n\r\n        if (top > bottom) {\r\n            break;\r\n        }\r\n\r\n        // Fill from top to bottom.\r\n        for (int i = top; i <= bottom; ++i) {\r\n            matrix[i][right] = currentChar;\r\n            currentChar = currentChar == 'Z' ? 'A' : currentChar + 1;  // Loop back to 'A' after 'Z'.\r\n        }\r\n        --right;\r\n\r\n        if (left > right) {\r\n            break;\r\n        }\r\n\r\n        // Fill from right to left.\r\n        for (int i = right; i >= left; --i) {\r\n            matrix[bottom][i] = currentChar;\r\n            currentChar = currentChar == 'Z' ? 'A' : currentChar + 1;  // Loop back to 'A' after 'Z'.\r\n        }\r\n        --bottom;\r\n\r\n        if (top > bottom) {\r\n            break;\r\n        }\r\n\r\n        // Fill from bottom to top.\r\n        for (int i = bottom; i >= top; --i) {\r\n            matrix[i][left] = currentChar;\r\n            currentChar = currentChar == 'Z' ? 'A' : currentChar + 1;  // Loop back to 'A' after 'Z'.\r\n        }\r\n        ++left;\r\n    }\r\n\r\n    return matrix;\r\n}\r\n\r\n// Utility function to print the matrix.\r\n// Utility function to print the upper/right diagonal of the matrix with stylized formatting.\r\nvoid printUpperRightDiagonalFormatted(const std::vector<std::vector<char>>& matrix) {\r\n    int n = matrix.size();\r\n    int cellWidth = 2;  // Adjust cell width as per the stylization requirement.\r\n    int totalWidth = n * (cellWidth + 1) + 1;  // Total width of the matrix including spaces and border.\r\n\r\n    // Print the top border.\r\n    std::cout << "+";\r\n    for (int i = 0; i < totalWidth - 2; ++i) {\r\n        std::cout << "=";\r\n    }\r\n    std::cout << "+\\n";\r\n\r\n    for (int i = 0; i < n; ++i) {\r\n        // Print leading backslashes and spaces for the lower/left side of the matrix.\r\n        std::cout << std::string(i + 1, ' ') << "\\\\";  // Each line starts with spaces and a backslash.\r\n\r\n        // Now, adjust the space after backslash based on the row number.\r\n//        for (int j = 0; j < i; ++j) {\r\n//            std::cout << std::setw(cellWidth + 1) << ' '; // Creating space for each invisible cell.\r\n//        }\r\n\r\n        // Print the upper/right diagonal elements with proper spacing.\r\n        for (int j = i; j < n; ++j) {\r\n            std::cout << std::setw(cellWidth) << matrix[i][j] << ' '; // Print characters with spaces.\r\n        }\r\n\r\n        // Next line after each row.\r\n        std::cout << "|\\n";  // Each line ends with a vertical bar.\r\n    }\r\n\r\n    // Print the bottom border.\r\n    std::cout << std::string(totalWidth - 1, ' ') << "+\\n";\r\n}\r\n\r\n// Main function to take matrix size input, generate spiral, and print it.\r\nint main() {\r\n    int n;\r\n    std::cout << "Enter size of matrix (n x n): ";\r\n    std::cin >> n;\r\n\r\n    if (n <= 0) {\r\n        std::cerr << "Size must be a positive integer." << std::endl;\r\n        return 1;\r\n    }\